public static void solve(FastScanner sc, FastPrintStream pw) throws Exception {
    int t = sc.nextInt();
    for (int times = 0; times < t; times++) {
        long n = sc.nextLong();
        long m = sc.nextLong();
        long k = sc.nextLong();
        int re[] = new int[] { 6, 2, 4, 8 };
        if (m > n + 1) {
            n = n % 4;
            pw.println(re[(int) n]);
        } else if (m == n + 1) {
            if (k == n) {
                pw.println(0);
            } else {
                n = n % 4;
                pw.println(re[(int) n]);
            }
        } else {
            // m <= n
            if (k == m - 1) {
                pw.println(0);
            } else {
                long temp = (n - k) / (m - k);
                temp = n - temp * (m - k);
                temp = temp % 4;
                pw.println(re[(int) temp]);
            }
        }
    }
}
